//
//  StashClient.swift
//  MizarKit
//
//  The phone's half of the offline stash: fetch what the computer wrote while
//  this phone was away, decrypt it, and acknowledge it.
//
//  The relay stores opaque bytes and knows nothing about Mizar, so everything
//  that makes a bundle readable lives here: two values derived from the pairing
//  token (a content key the relay never sees, and a pull credential it compares)
//  and the AEAD framing around the bundle JSON. The cross-language ground truth
//  is `protocol/fixtures/stash/vectors.json`, generated by
//  `tools/gen-stash-fixtures.mjs` and read by the desktop as well -- a drift in
//  either side's derivation is a bundle that silently fails to open.
//
//  Nothing in this file is UI and nothing in it reaches a host: the phone only
//  talks to the relay's HTTP endpoints under its room, and only when the
//  computer is not answering.
//

import CryptoKit
import Foundation

// MARK: - Derivation

/// The two values one pairing gives the stash, and the room they belong to.
///
/// `key` decrypts; `cred` identifies this phone to the relay. The relay holds a
/// copy of `cred` (the desktop registered it) and never the key, and `cred`
/// cannot be turned back into the pairing token -- which is why pulling a
/// bundle does not widen what a compromised relay can read.
public struct StashCredentials: Sendable, Equatable {
    /// The relay room, taken from the pairing's relay base URL.
    public let room: String
    /// `SHA-256(token)`, lowercase hex. Also what the desktop stores, so this is
    /// the same value, not a second hash of the same secret.
    public let tokenHash: String
    /// The 32-byte content key, as bytes so a test can compare it with the
    /// cross-language vector.
    public let keyBytes: Data
    /// The pull credential the relay compares: a hash, so the relay cannot
    /// derive the key from it.
    public let cred: String

    /// The key, in the form CryptoKit's AEAD takes.
    public var key: SymmetricKey { SymmetricKey(data: keyBytes) }

    /// The HKDF info string, spelled identically in Rust and Swift.
    public static let keyInfo = "mizar/offline-stash/v1"

    /// The prefix inside the pull credential's hash.
    public static let credPrefix = "mizar/offline-stash/cred:v1"

    /// Derive the two values from a pairing.
    ///
    /// - Parameters:
    ///   - deviceToken: the plaintext pairing token, from the Keychain.
    ///   - room: the relay room this pairing lives in.
    /// - Returns: the credentials, or `nil` when either input is empty.
    public init?(deviceToken: String, room: String) {
        guard !deviceToken.isEmpty, !room.isEmpty else { return nil }
        self.room = room
        let digest = StashCredentials.sha256Hex(deviceToken)
        tokenHash = digest
        // HKDF over the *hex digest*, not the token: the desktop only ever holds
        // the digest, and deriving from the digest is what lets an existing
        // pairing work without a new handshake or a re-pair.
        let derived = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: Data(digest.utf8)),
            salt: Data(room.utf8),
            info: Data(StashCredentials.keyInfo.utf8),
            outputByteCount: 32,
        )
        keyBytes = derived.withUnsafeBytes { Data($0) }
        cred = StashCredentials.sha256Hex("\(StashCredentials.credPrefix)\(digest)\(room)")
    }

    /// Derive from a pairing's relay base URL, parsing the room out of it.
    ///
    /// - Parameters:
    ///   - relayBaseURL: the relay base, `https://relay.example.com/r/ROOM`.
    ///   - deviceToken: the plaintext pairing token.
    /// - Returns: the credentials, or `nil` when the URL names no room.
    public init?(relayBaseURL: String, deviceToken: String) {
        guard let room = StashCredentials.room(inRelayBaseURL: relayBaseURL) else { return nil }
        self.init(deviceToken: deviceToken, room: room)
    }

    /// SHA-256 as lowercase hex.
    ///
    /// The same shape as `LiveActivityHostIdentity`'s credential digest, and
    /// deliberately a second copy of three lines rather than a shared helper:
    /// this one is a wire contract with a Rust implementation, so it should be
    /// read here, in the file that documents the contract.
    ///
    /// - Parameter text: the UTF-8 input.
    /// - Returns: 64 lowercase hex characters.
    public static func sha256Hex(_ text: String) -> String {
        SHA256.hash(data: Data(text.utf8)).map { String(format: "%02x", $0) }.joined()
    }

    /// The room at the end of a relay base URL.
    ///
    /// The relay hands out bases of the shape `https://host/r/ROOM`, and the
    /// room is the last path component. Trailing slashes are tolerated because
    /// a stored base URL is whatever the pairing wrote down.
    ///
    /// - Parameter relayBaseURL: the base URL.
    /// - Returns: the room, or `nil` when there is no last component.
    public static func room(inRelayBaseURL relayBaseURL: String) -> String? {
        guard let url = URL(string: relayBaseURL) else { return nil }
        let parts = url.path.split(separator: "/", omittingEmptySubsequences: true)
        guard let last = parts.last, !last.isEmpty else { return nil }
        return String(last)
    }
}

// MARK: - The envelope

/// The AEAD framing of one bundle.
///
/// `[1 byte version][1 byte reserved][12 byte nonce][ciphertext || 16 byte tag]`.
/// The version byte is outside the seal on purpose: an unknown version must be
/// skippable without a key, and it is the byte that lets a future algorithm
/// change stay backwards compatible.
public enum StashEnvelope {
    /// The only envelope version this build understands.
    public static let version: UInt8 = 1

    /// Nonce width, fixed by ChaCha20-Poly1305's IETF framing.
    public static let nonceByteCount = 12

    /// The AAD one envelope is bound to.
    ///
    /// The separator and the order are the wire: the desktop builds the same
    /// string, and an envelope opened with a different one fails authentication
    /// rather than decrypting to the wrong bundle.
    ///
    /// - Parameters:
    ///   - room: the relay room.
    ///   - hostId: the computer's identity.
    ///   - deviceId: the phone's identity.
    ///   - bundleId: the relay's id for this bundle.
    ///   - createdAt: the bundle's creation time, epoch milliseconds.
    /// - Returns: the AAD string.
    public static func aad(
        room: String,
        hostId: String,
        deviceId: String,
        bundleId: String,
        createdAt: Int64,
    ) -> String {
        "v1|\(room)|\(hostId)|\(deviceId)|\(bundleId)|\(createdAt)"
    }

    /// Seal one plaintext into an envelope.
    ///
    /// - Parameters:
    ///   - plaintext: the bundle JSON's bytes.
    ///   - key: the content key.
    ///   - nonce: 12 random bytes.
    ///   - aad: ``aad(room:hostId:deviceId:bundleId:createdAt:)``.
    /// - Returns: the envelope bytes.
    /// - Throws: ``StashError/malformedEnvelope`` for a nonce of the wrong size.
    public static func seal(
        plaintext: Data,
        key: SymmetricKey,
        nonce: Data,
        aad: String,
    ) throws -> Data {
        guard nonce.count == nonceByteCount else { throw StashError.malformedEnvelope }
        let box = try ChaChaPoly.seal(
            plaintext,
            using: key,
            nonce: try ChaChaPoly.Nonce(data: nonce),
            authenticating: Data(aad.utf8),
        )
        return Data([version, 0]) + nonce + box.ciphertext + box.tag
    }

    /// Open one envelope.
    ///
    /// - Parameters:
    ///   - envelope: the bytes the relay stored.
    ///   - key: the content key.
    ///   - aad: the AAD the desktop bound it to.
    /// - Returns: the plaintext bytes.
    /// - Throws: ``StashError/unsupportedVersion`` when the version byte is not
    ///   ``version``; ``StashError/malformedEnvelope`` when the frame is short;
    ///   ``StashError/authenticationFailed`` when the seal does not verify.
    public static func open(_ envelope: Data, key: SymmetricKey, aad: String) throws -> Data {
        // A copy, so the indices below are the frame's own even when the caller
        // handed over a slice.
        let envelope = Data(envelope)
        let header = 2 + nonceByteCount
        let tagByteCount = 16
        guard envelope.count >= header + tagByteCount else { throw StashError.malformedEnvelope }
        // Only the version byte; the reserved byte is deliberately not read, so
        // a future writer may use it without breaking a phone that does not.
        guard envelope[envelope.startIndex] == version else { throw StashError.unsupportedVersion }
        let nonceStart = envelope.startIndex + 2
        let nonce = envelope[nonceStart..<nonceStart + nonceByteCount]
        let sealed = envelope[(nonceStart + nonceByteCount)...]
        do {
            // `SealedBox(combined:)` is nonce || ciphertext || tag, which is the
            // framing this envelope uses once the two header bytes are off.
            return try ChaChaPoly.open(
                try ChaChaPoly.SealedBox(combined: Data(nonce) + Data(sealed)),
                using: key,
                authenticating: Data(aad.utf8),
            )
        } catch {
            throw StashError.authenticationFailed
        }
    }
}

// MARK: - The bundle

/// One encrypted bundle's plaintext, as the desktop wrote it.
///
/// Field names follow `docs/desktop/offline-stash-wire-v1.md` §3. Everything but
/// `v`, `turns` and the identity fields is decodable when absent: a bundle from a
/// slightly newer desktop should still yield its process text rather than
/// nothing at all.
public struct StashBundle: Codable, Sendable, Equatable {
    public let v: Int
    public let bundleId: String
    public let room: String
    public let hostId: String
    public let deviceId: String
    /// The desktop process instance, so a restart is visible.
    public let epoch: Int
    public let createdAt: Int64
    public let turns: [Turn]

    enum CodingKeys: String, CodingKey {
        case v, room, epoch, createdAt, turns
        case bundleId, hostId, deviceId
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        v = try container.decodeIfPresent(Int.self, forKey: .v) ?? 1
        bundleId = try container.decodeIfPresent(String.self, forKey: .bundleId) ?? ""
        room = try container.decodeIfPresent(String.self, forKey: .room) ?? ""
        hostId = try container.decodeIfPresent(String.self, forKey: .hostId) ?? ""
        deviceId = try container.decodeIfPresent(String.self, forKey: .deviceId) ?? ""
        // A host used to seal a random 64-bit value here, and this is decoded
        // into a signed integer: half of those bundles threw out of range and
        // were acknowledged without ever being shown. The number only has to
        // tell one process from the next, so its bit pattern is kept either way.
        if let signed = try? container.decodeIfPresent(Int64.self, forKey: .epoch) {
            epoch = Int(truncatingIfNeeded: signed)
        } else if let unsigned = try? container.decodeIfPresent(UInt64.self, forKey: .epoch) {
            epoch = Int(truncatingIfNeeded: unsigned)
        } else {
            epoch = 0
        }
        createdAt = try container.decodeIfPresent(Int64.self, forKey: .createdAt) ?? 0
        turns = try container.decodeIfPresent([Turn].self, forKey: .turns) ?? []
    }

    public init(
        v: Int = 1,
        bundleId: String,
        room: String,
        hostId: String,
        deviceId: String,
        epoch: Int = 0,
        createdAt: Int64,
        turns: [Turn],
    ) {
        self.v = v
        self.bundleId = bundleId
        self.room = room
        self.hostId = hostId
        self.deviceId = deviceId
        self.epoch = epoch
        self.createdAt = createdAt
        self.turns = turns
    }

    /// One turn's journal, shaped exactly like `session.stream`'s replay.
    public struct Turn: Codable, Sendable, Equatable {
        public let sessionId: String
        public let turn: Int
        /// Epoch milliseconds; `0` means the turn had not ended when it was written.
        public let startedAt: Int64
        public let endedAt: Int64
        public let state: UInt8
        public let interval: UInt32
        public let textSeq: UInt32
        public let truncated: Bool
        public let entries: [StreamReplay.Entry]

        enum CodingKeys: String, CodingKey {
            case turn, startedAt, endedAt, state, interval, textSeq, truncated, entries
            case sessionId
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            sessionId = try container.decode(String.self, forKey: .sessionId)
            turn = try container.decode(Int.self, forKey: .turn)
            startedAt = try container.decodeIfPresent(Int64.self, forKey: .startedAt) ?? 0
            endedAt = try container.decodeIfPresent(Int64.self, forKey: .endedAt) ?? 0
            state = try container.decodeIfPresent(UInt8.self, forKey: .state) ?? 0
            interval = try container.decodeIfPresent(UInt32.self, forKey: .interval) ?? 0
            textSeq = try container.decodeIfPresent(UInt32.self, forKey: .textSeq) ?? 0
            truncated = try container.decodeIfPresent(Bool.self, forKey: .truncated) ?? false
            // `entries` is the whole point of a bundle. A missing one is a turn
            // with nothing to replay, which is valid rather than an error.
            entries = try container.decodeIfPresent([StreamReplay.Entry].self, forKey: .entries) ?? []
        }

        public init(
            sessionId: String,
            turn: Int,
            startedAt: Int64,
            endedAt: Int64,
            state: UInt8,
            interval: UInt32,
            textSeq: UInt32,
            truncated: Bool,
            entries: [StreamReplay.Entry],
        ) {
            self.sessionId = sessionId
            self.turn = turn
            self.startedAt = startedAt
            self.endedAt = endedAt
            self.state = state
            self.interval = interval
            self.textSeq = textSeq
            self.truncated = truncated
            self.entries = entries
        }

        /// When the turn began, or `nil` when the writer did not say.
        public var startedDate: Date? {
            startedAt > 0 ? Date(timeIntervalSince1970: Double(startedAt) / 1000) : nil
        }

        /// When it ended, or `nil` for a turn that was still running.
        public var endedDate: Date? {
            endedAt > 0 ? Date(timeIntervalSince1970: Double(endedAt) / 1000) : nil
        }

        /// The journal, in the shape the rest of the app already reads.
        public var replay: StreamReplay {
            StreamReplay(
                sessionId: sessionId,
                turn: turn,
                state: state,
                interval: interval,
                textSeq: textSeq,
                truncated: truncated,
                entries: entries,
            )
        }

        /// The turn's answer: the text of the interval the `final` marker landed in.
        ///
        /// Within one interval the first entry is that interval's text so far and
        /// later entries are appends, so the answer is the concatenation of the
        /// whole final interval -- not only the entry that carries the flag. A
        /// bundle that ended on narration has no final interval and no answer.
        public var bodyText: String? {
            guard let finalEntry = entries.last(where: \.final) else { return nil }
            let finalInterval = finalEntry.interval
            let text = entries
                .filter { $0.interval == finalInterval }
                .map(\.text)
                .joined()
            return text.isEmpty ? nil : text
        }
    }
}

// MARK: - HTTP

/// One envelope as the relay hands it to a pull.
public struct StashPulledEnvelope: Sendable, Equatable {
    /// The relay's id for the bundle; what an ACK names.
    public let bundleId: String
    /// The session the bundle is about, as the desktop wrote it on the put.
    public let sessionId: String
    /// Epoch milliseconds.
    public let createdAt: Int64
    /// The envelope's size, when the relay says.
    public let bytes: Int
    /// The envelope itself.
    public let envelope: Data

    public init(
        bundleId: String,
        sessionId: String,
        createdAt: Int64,
        bytes: Int = 0,
        envelope: Data,
    ) {
        self.bundleId = bundleId
        self.sessionId = sessionId
        self.createdAt = createdAt
        self.bytes = bytes
        self.envelope = envelope
    }
}

/// What a pull came back with.
public enum StashPullResult: Sendable, Equatable {
    /// Envelopes, oldest first as the relay ordered them.
    case bundles([StashPulledEnvelope])
    /// The relay has no stash for this room and credential: an old relay, a
    /// self-hosted one without the feature, or a room whose letters were
    /// withdrawn because the computer came back. All three mean "behave as
    /// before", and none is an error to show anyone.
    case notAvailable
}

/// Failures the caller is expected to swallow.
public enum StashError: Error, Sendable, Equatable {
    case malformedEnvelope
    case unsupportedVersion
    case authenticationFailed
    case malformedResponse
    case httpStatus(Int)
    case badURL
}

/// The relay's stash endpoints, for one pairing.
///
/// A value, not an actor: it holds no state beyond the credentials and the
/// transport, so two calls from two tasks cannot disagree about anything.
public struct StashClient: Sendable {
    /// What this pairing derives.
    public let credentials: StashCredentials
    /// The relay base, room path included.
    public let relayBaseURL: String
    /// The computer's identity, as the AAD spells it.
    public let hostId: String
    /// This phone's identity, as the AAD spells it.
    public let deviceId: String

    private let transport: any HTTPTransport

    /// The account headers this relay is owed, if any.
    ///
    /// A closed relay answers nothing without a session, and the pull is the one
    /// request the phone makes outside the session socket. Empty for an ordinary
    /// relay, which is every relay that is not gated by account.
    private let sessionHeaders: [String: String]

    /// One client for one pairing.
    ///
    /// - Parameters:
    ///   - relayBaseURL: the pairing's relay base URL.
    ///   - hostId: the paired host's id.
    ///   - deviceId: the paired device's id.
    ///   - deviceToken: the plaintext token.
    ///   - transport: where requests go. Injectable so tests never open a socket.
    /// - Returns: `nil` when the base URL names no room.
    public init?(
        relayBaseURL: String,
        hostId: String,
        deviceId: String,
        deviceToken: String,
        sessionHeaders: [String: String] = [:],
        transport: any HTTPTransport = URLSessionHTTPTransport(),
    ) {
        guard let credentials = StashCredentials(relayBaseURL: relayBaseURL, deviceToken: deviceToken) else {
            return nil
        }
        self.credentials = credentials
        self.relayBaseURL = relayBaseURL
        self.hostId = hostId
        self.deviceId = deviceId
        self.sessionHeaders = sessionHeaders
        self.transport = transport
    }

    /// The AAD the desktop bound one envelope to.
    ///
    /// Both identities come from the pairing, not from the relay: the pull
    /// response does not carry them, and a bundle's own copy is inside the
    /// ciphertext it would authenticate.
    ///
    /// - Parameter pulled: the envelope, for its id and creation time.
    /// - Returns: the AAD string.
    public func aad(for pulled: StashPulledEnvelope) -> String {
        StashEnvelope.aad(
            room: credentials.room,
            hostId: hostId,
            deviceId: deviceId,
            bundleId: pulled.bundleId,
            createdAt: pulled.createdAt,
        )
    }

    /// Fetch the letters waiting for this phone.
    ///
    /// - Parameter max: how many to ask for, clamped by the relay's own ceiling.
    /// - Returns: the envelopes, or ``StashPullResult/notAvailable`` for a relay
    ///   that has no stash for this room.
    /// - Throws: ``StashError`` for a non-404 failure and for a body that is not
    ///   the pull contract.
    public func pull(max: Int = 32) async throws -> StashPullResult {
        guard let url = PairingURI.relayHTTPURL(
            baseURL: relayBaseURL,
            path: "/stash/v1/pull?max=\(max)",
        ) else { throw StashError.badURL }
        var request = URLRequest(url: url)
        request.httpMethod = "GET"
        request.timeoutInterval = 15
        request.setValue(credentials.cred, forHTTPHeaderField: "x-stash-cred")
        for (name, value) in sessionHeaders { request.setValue(value, forHTTPHeaderField: name) }
        // A stash read must never be answered from a cache: the letters are
        // deleted the moment they are acknowledged, and a cached 200 would
        // deliver the same turn twice.
        request.cachePolicy = .reloadIgnoringLocalCacheData
        let (data, response) = try await transport.data(for: request)
        if response.statusCode == 404 { return .notAvailable }
        guard (200..<300).contains(response.statusCode) else {
            throw StashError.httpStatus(response.statusCode)
        }
        guard let body = try? JSONDecoder().decode(PullResponse.self, from: data) else {
            throw StashError.malformedResponse
        }
        return .bundles(body.bundles.compactMap(\.pulled))
    }

    /// Decrypt and decode one pulled envelope.
    ///
    /// Never throws: an envelope this build cannot open is skipped, per the wire
    /// contract, because the alternative is a phone that shows an error for
    /// something the operator cannot act on.
    ///
    /// - Parameter pulled: one entry of a pull.
    /// - Returns: the bundle, or `nil` for a bad version, a failed seal, or JSON
    ///   that is not a bundle.
    public func open(_ pulled: StashPulledEnvelope) -> StashBundle? {
        guard let plaintext = try? StashEnvelope.open(
            pulled.envelope,
            key: credentials.key,
            aad: aad(for: pulled),
        ) else { return nil }
        guard let bundle = try? JSONDecoder().decode(StashBundle.self, from: plaintext) else {
            return nil
        }
        // The bundle's own version, in case a writer sealed a newer schema
        // under the version byte this build knows.
        guard bundle.v == 1 else { return nil }
        return bundle
    }

    /// Tell the relay these bundles are dealt with.
    ///
    /// Sent for every pulled id, applied or skipped: a bundle this phone cannot
    /// open would otherwise be fetched on every launch for seven days.
    ///
    /// - Parameter bundleIds: the relay ids to delete.
    /// - Throws: ``StashError`` for a failed request. Callers ack best-effort.
    public func ack(bundleIds: [String]) async throws {
        guard !bundleIds.isEmpty else { return }
        guard let url = PairingURI.relayHTTPURL(baseURL: relayBaseURL, path: "/stash/v1/ack") else {
            throw StashError.badURL
        }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.timeoutInterval = 15
        request.setValue(credentials.cred, forHTTPHeaderField: "x-stash-cred")
        for (name, value) in sessionHeaders { request.setValue(value, forHTTPHeaderField: name) }
        request.setValue("application/json", forHTTPHeaderField: "content-type")
        request.httpBody = try JSONEncoder().encode(AckBody(bundleIds: bundleIds))
        let (_, response) = try await transport.data(for: request)
        guard (200..<300).contains(response.statusCode) else {
            throw StashError.httpStatus(response.statusCode)
        }
    }

    /// The pull response, decoded.
    private struct PullResponse: Decodable {
        let bundles: [Entry]

        struct Entry: Decodable {
            let bundleId: String
            let sessionId: String?
            let createdAt: Int64?
            let bytes: Int?
            /// Base64 in the wire JSON; `Data`'s own decoding does that here.
            let envelope: Data?

            /// The entry as the public shape, or `nil` when it names no bundle.
            var pulled: StashPulledEnvelope? {
                guard let envelope else { return nil }
                return StashPulledEnvelope(
                    bundleId: bundleId,
                    sessionId: sessionId ?? "",
                    createdAt: createdAt ?? 0,
                    bytes: bytes ?? envelope.count,
                    envelope: envelope,
                )
            }
        }
    }

    /// The ACK body.
    private struct AckBody: Encodable {
        let bundleIds: [String]
    }
}
